/// <summary>
/// Event handler class for <c>PriceDiscAdmTrans</c> data source of <c>PriceDiscAdm</c> form
/// </summary>
class GUPPriceDiscAdmTransDSFormEventHandler
{   
}

Method.Source:
/// <summary>
/// Set Item code and account code to All for Unified pricing module
/// </summary>
/// <param name="_sender">PriceDiscAdmTrans data source</param>
/// <param name="_e">Other parameter</param>
[FormDataSourceEventHandler(formDataSourceStr(PriceDiscAdm, PriceDiscAdmTrans), FormDataSourceEventType::InitValue)]
public static void PriceDiscAdmTrans_OnInitValue(FormDataSource _sender, FormDataSourceEventArgs _e)
{
    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        PriceDiscAdmTrans priceDiscAdmTrans = _sender.cursor();

        if (priceDiscAdmTrans.isPricingAttributeEnabled())
        {
            PriceDiscAdmTable priceDiscAdmTable = PriceDiscAdmTable::find(priceDiscAdmTrans.JournalNum);

            priceDiscAdmTrans.PriceComponentCombination = priceDiscAdmTable.PriceComponentCombination;
            priceDiscAdmTrans.PriceApplyAdjustment = priceDiscAdmTable.PriceApplyAdjustment;

            priceDiscAdmTrans.ItemCode = PriceDiscProductCodeType::All;
            priceDiscAdmTrans.AccountCode = PriceDiscPartyCodeType::All;

            if (!GUPParameters::find().PriceDiscSearchAgainDefault)
            {
                priceDiscAdmTrans.SearchAgain = NoYes::No;
            }
        }
    }
}

/// <summary>
/// Force write datasource for being able to edit pricing attribute groups
/// </summary>
/// <param name="_sender">PriceDiscAdmTrans data source</param>
/// <param name="_e">Other parameter</param>
[FormDataSourceEventHandler(formDataSourceStr(PriceDiscAdm, PriceDiscAdmTrans), FormDataSourceEventType::Created)]
public static void PriceDiscAdmTrans_OnCreated(FormDataSource _sender, FormDataSourceEventArgs _e)
{
    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        PriceDiscAdmTrans priceDiscAdmTrans = _sender.cursor();
        FormRun formRun = _sender.formRun();

        if (!formRun.isRecordCopy() && priceDiscAdmTrans.isPricingAttributeEnabled())
        {
            _sender.write();

            if (!priceDiscAdmTrans.PricingRuleHeader && !priceDiscAdmTrans.PricingRuleLine)
            {
                Args args = new Args();
                args.record(priceDiscAdmTrans);
                args.parmEnum(FormDataSourceEventType::Created);
                args.parmEnumType(enumNum(FormDataSourceEventType));

                new MenuFunction(menuItemDisplayStr(GUPPriceDiscPriceAttributeGroupEdit), MenuItemType::Display).run(args);
            }
        }
    }
}
